/* ==========================================================================
   SOCIAL POSTS

   Generated from the markdown in /social by scripts/parse-social.py, which is
   the authority — edit the markdown and re-run it rather than editing here.

   The markdown stays because it is what a person reads and edits in bulk.
   This module exists so the same content is browsable and markable in the
   admin, where the day-to-day job actually happens: find today's post, copy
   the caption, tick it off.

   `status` is NOT stored here. It lives in MongoDB, keyed by `key`, so
   re-generating this file never resets what you have already published.
   ========================================================================== */

export type SocialSource = "calendar" | "library" | "google" | "reel";

export type SocialPost = {
  /** Stable identity across regenerations. Status is keyed on this. */
  key: string;
  source: SocialSource;
  /** Day, service or collection this belongs to. */
  group: string;
  theme: string;
  /** Posting slot, or a reel's length. */
  slot: string;
  format: string;
  title: string;
  hook: string;
  /** Timed script — reels only. */
  script: string;
  caption: string;
  /** Hashtag recipe, or the finished string for Google posts. */
  hashtags: string;
  imagePrompt: string;
  /** Calendar day number; 0 for everything else. */
  day: number;
  order: number;
};

